'use strict';

// v1226 realm map (Phil 30 Oct 2026: "put this map in game. Swap out the old one"): the four continents ARE the four home regions,
// the island under the World Tree IS the worldtree zone, the islets are the wild, and every sea / off-realm cell is blocked.
// Which cell is which comes from ../world-realm.js, GENERATED by tools/realm/build_realm.py (never hand-edited).
// v1227 (Phil 30 Oct 2026: "The tiles need to be roughly 2x smaller ... Then fix the zoom to that level", then "about 1000 wide by
// about 600 tall"): the grid is REALM.META.cols x REALM.META.rows square cells (1000 x 596) - GRID_COLS / GRID_ROWS in the build,
// read here, never typed again. Positions stay world-percent of the square 0..100 world and are never migrated. Nothing that is not
// a grid square changed its world size: a castle still covers one 220-grid square, so it covers FOOT x FOOT cells (4 x 4) and its
// position is the corner they share; an old castle keeps its exact position and simply covers the 4 x 4 cells around it.
// Initial placement is server-owned and never derived from the browser's save.
const crypto=require('node:crypto');
const REALM=require('../world-realm.js');
const GEO=REALM.GEO;
const GRID_COLS=GEO.COLS, GRID_ROWS=GEO.ROWS, CELL=GEO.CELL, FOOT=GEO.FOOT, MARCH_SQUARE=GEO.OLD_SQUARE;
// col/row = the quadrant each continent sits in (0 west/north, 2 east/south)
const REGIONS=Object.freeze({
  crystor:{col:0,row:0},draymon:{col:2,row:0},
  tefron:{col:0,row:2},alumron:{col:2,row:2}
});
const REGION_KEYS=Object.freeze(Object.keys(REGIONS));
if(!(GRID_COLS>0&&GRID_ROWS>0&&FOOT>0)) throw Error('world-realm.js has no grid');
for(const k of REGION_KEYS) if(!REALM.zoneCells(k).length) throw Error('world-realm.js: region '+k+' has no land');
const col=GEO.col, row=GEO.row, xOf=GEO.xOf, yOf=GEO.yOf, anchorX=GEO.anchorX, anchorY=GEO.anchorY, cornerX=GEO.cornerX, cornerY=GEO.cornerY;
const footprint=GEO.footprint, footKeys=GEO.footKeys, coreCell=GEO.coreCell, marchSquares=GEO.marchSquares;
function castleKey(x,y){ return anchorX(x)+','+anchorY(y); }   // one key per castle square (its top-left cell)
function footBlocked(blocked,x,y){ return footKeys(x,y).some(k=>blocked.has(k)); }
// the zone of a position: the zone of the castle square's first cell (a castle square never spans two zones - sea parts them)
function zoneOf(x,y){ const [cx,cy]=footprint(x,y)[0]; return REALM.zoneOfCell(cx,cy); }
// a castle square is land only when all its cells are land
function isLand(x,y){ return footprint(x,y).every(([cx,cy])=>REALM.isLand(cx,cy)); }
// Phil 30 Oct 2026: "the city should not be able to be teleported onto" - a castle square touching a city cell is blocked like the sea
function isCity(x,y){ return footprint(x,y).some(([cx,cy])=>REALM.isCity(cx,cy)); }
// v1228: an oasis (Grok's painted pond) is a garrison site like a city - blocked the same way
function isOasis(x,y){ return footprint(x,y).some(([cx,cy])=>REALM.isOasis(cx,cy)); }
function isSite(x,y){ return footprint(x,y).some(([cx,cy])=>REALM.isSite(cx,cy)); }
function cellKey(x,y){ return col(x)+','+row(y); }
function treeCore(x,y){ return footprint(x,y).some(([cx,cy])=>coreCell(cx,cy)); }
function targetAllowed(home,x,y){
  if(!REGIONS[home]||!Number.isFinite(x)||!Number.isFinite(y)||x<0||x>100||y<0||y>100) return false;
  return footprint(x,y).every(([cx,cy])=>{ const z=REALM.landZone(cx,cy);
    return !!z&&!REALM.isSite(cx,cy)&&!coreCell(cx,cy)&&(!REGIONS[z]||z===home); });
}
// the castle square of `region` whose top-left cell is (ax,ay): every cell that region's open land, none blocked
function regionSquare(region,ax,ay,occupied){
  if(ax<0||ay<0||ax>GRID_COLS-FOOT||ay>GRID_ROWS-FOOT) return false;
  for(let j=0;j<FOOT;j++) for(let i=0;i<FOOT;i++){ const cx=ax+i,cy=ay+j;
    if(REALM.landZone(cx,cy)!==region||REALM.isSite(cx,cy)||occupied.has(cx+','+cy)) return false; }
  return true;
}
const at=(region,cx,cy)=>({region,x:cornerX(cx),y:cornerY(cy)});
// a region's land cells, in row order, as castle-square starts; `preferred` is an index into that list (wraps)
function openInRegion(region,blocked=[],randomInt=crypto.randomInt,preferred){
  if(!REGIONS[region]) return null;
  const cells=REALM.zoneCells(region), occupied=blocked instanceof Set?blocked:new Set(blocked), n=cells.length;
  const start=preferred==null?randomInt(n):((preferred%n)+n)%n;
  for(let i=0;i<n;i++){
    const [cx,cy]=cells[(start+i)%n];
    if(regionSquare(region,cx,cy,occupied)) return at(region,cx,cy);
  }
  return null;
}
// the nearest open castle square of the castle's OWN home region (the relocation rule: a castle the map puts in the sea,
// or in another region, moves to the nearest land of its own region)
function nearestInRegion(home,x,y,blocked=[]){
  if(!REGIONS[home]||!Number.isFinite(x)||!Number.isFinite(y)) return null;
  const occupied=blocked instanceof Set?blocked:new Set(blocked), fromX=anchorX(x), fromY=anchorY(y);
  let best=null,bestDistance=Infinity;
  for(const [cx,cy] of REALM.zoneCells(home)){
    const distance=(cx-fromX)**2+(cy-fromY)**2;
    if(distance>=bestDistance||!regionSquare(home,cx,cy,occupied)) continue;
    best=at(home,cx,cy); bestDistance=distance;
  }
  return best;
}
// the nearest castle square this castle may stand on (own region, wild islets or the World Tree island)
function nearestOpen(home,x,y,blocked=[]){
  if(!REGIONS[home]||!Number.isFinite(x)||!Number.isFinite(y)) return null;
  const occupied=new Set(blocked);
  const fromX=anchorX(x),fromY=anchorY(y);
  let best=null,bestDistance=Infinity;
  for(let cy=0;cy<=GRID_ROWS-FOOT;cy++) for(let cx=0;cx<=GRID_COLS-FOOT;cx++){
    const distance=(cx-fromX)**2+(cy-fromY)**2;
    if(distance>=bestDistance) continue;
    const px=cornerX(cx),py=cornerY(cy);
    if(footBlocked(occupied,px,py)||!targetAllowed(home,px,py)) continue;
    best={region:home,x:px,y:py}; bestDistance=distance;
  }
  return best;
}
function valid(loc){
  if(!loc||!REGIONS[loc.region]||!Number.isFinite(loc.x)||!Number.isFinite(loc.y)) return false;
  return targetAllowed(loc.region,loc.x,loc.y);
}
// a position snapped to the castle square nearest to it (a teleport target)
function snap(x,y){ return {x:cornerX(anchorX(x)),y:cornerY(anchorY(y))}; }
function place(existing,randomInt=crypto.randomInt,blocked=[]){
  const locations=(existing||[]).filter(valid);
  const occupied=new Set(locations.flatMap(loc=>footKeys(loc.x,loc.y)));
  for(const key of blocked) occupied.add(key);
  const counts=Object.fromEntries(REGION_KEYS.map(k=>[k,0]));
  for(const loc of locations) counts[loc.region]++;
  // Fill the least populated home region first. Equal counts use a random tie break.
  const order=REGION_KEYS.map(region=>({region,count:counts[region],tie:randomInt(0x7fffffff)}))
    .sort((a,b)=>a.count-b.count||a.tie-b.tie);
  for(const {region} of order){
    const cells=REALM.zoneCells(region), n=cells.length, start=randomInt(n);
    for(let i=0;i<n;i++){
      const [cx,cy]=cells[(start+i)%n];
      if(regionSquare(region,cx,cy,occupied)) return at(region,cx,cy);
    }
  }
  throw Error('No free castle square remains in the home regions.');
}
module.exports={GRID_COLS,GRID_ROWS,CELL,FOOT,MARCH_SQUARE,REGIONS,REGION_KEYS,REALM,GEO,col,row,xOf,yOf,anchorX,anchorY,cornerX,cornerY,
  footprint,footKeys,castleKey,footBlocked,coreCell,zoneOf,isLand,isCity,isOasis,isSite,cellKey,treeCore,targetAllowed,regionSquare,openInRegion,
  nearestInRegion,nearestOpen,valid,snap,marchSquares,place};
